//! Cookie import render responsibilities.
use crate::row::CookieRow;

pub(super) fn render_netscape_cookie_file(rows: &[CookieRow]) -> String {
    let mut lines = vec![
        "# Netscape HTTP Cookie File".to_string(),
        "# Generated by codetether auth cookies".to_string(),
    ];
    lines.extend(rows.iter().map(|row| {
        let domain = if row.http_only {
            format!("#HttpOnly_{}", row.domain)
        } else {
            row.domain.clone()
        };
        format!(
            "{}\t{}\t{}\t{}\t{}\t{}\t{}",
            domain,
            bool_flag(row.include_subdomains),
            row.path,
            bool_flag(row.secure),
            row.expires_epoch,
            row.name,
            row.value
        )
    }));
    format!("{}\n", lines.join("\n"))
}

pub(super) fn bool_flag(value: bool) -> &'static str {
    if value { "TRUE" } else { "FALSE" }
}
